const uint64_t Mod = 1000000007;

template<typename T>
static T FastPow(const T a, const T p)
{
    T res = 1;

    T mask = 1;
    T powPart = a;

    const size_t bitsCount = sizeof(T) * 8;
    for (size_t i = 0; i < bitsCount; i++)
    {
        if (p & mask)
        {
            res *= powPart;
            res %= Mod;
        }
        mask <<= 1;
        powPart *= powPart;
        powPart %= Mod;
    }

    return res;
}

bool Solve(std::istream& ist, std::ostream& ost, const bool multipleTestMode)
{
    StopWatch<1> sw; (void)sw;

    // 
    uint64_t p, k;
    ist >> p >> k;

    if (multipleTestMode && !ist)
        return false;

    LOCAL_PRINT() << std::endl << "Next test: " << p << " " << k << std::endl;
    //

    if (k == 0)
    {
        const uint64_t ans = FastPow(p, p - 1);
        ost << ans << std::endl;
        return multipleTestMode;
    }

    if (k == 1)
    {
        const uint64_t ans = FastPow(p, p);
        ost << ans << std::endl;
        return multipleTestMode;
    }

    uint64_t groups = 0;

    vector_size_t used(p + 1);
    uint64_t ans = 1;

    for (uint64_t x = 1; x < p; x++)
    {
        if (used[x])
            continue;

        groups += 1;
        ans *= p;
        ans %= Mod;

        used[x] = 1;

        uint64_t v = x;
        while (!used[v * k % p])
        {
            used[v * k % p] = 1;
            v = v * k % p;
        }
    }

    ost << ans << std::endl;

    return multipleTestMode;
}


